let lead = arrange([8, verse], [8, verse.add(2)], [8, verse.rev()], [8, verse.add(-1)],
  [8, verse.add(2)], [8, verse.rev().add(2)], [8, verse.add(-1).rev()], [8, verse])

stack(
  // 0: drone and choir
  note("e1").s("sawtooth").attack(1.5).release(3).gain(.3).lpf(160),
  note("e2").s("triangle").attack(1.5).release(3).gain(.35),
  chord(P).voicing().mode("below:e5")
    .s("sawtooth").lpq(4).attack(1.2).release(2.5).gain(.16)
    .lpf(2500).room(.9).roomsize(6).orbit(2),
  n(lead).scale("e4:spanish")
    .s("whistle").gain(.55).attack(.1).release(.9).lpf(2800).room(.8).roomsize(6).orbit(2),
  // 1: glass bells, a slow pulse
  layer(1, stack(
    n("<[0 ~ 2 ~ 4 ~ 2 ~] [1 ~ 3 ~ 5 ~ 3 ~]>".add("<0 0 2 0 -1 0 3 0>")).scale("e4:spanish")
      .s("bells").gain(.45).room(.9).roomsize(6).orbit(2),
    note("e2 ~ ~ ~ e2 ~ ~ ~").s("sine").decay(.5).sustain(0).gain(.55))),
  // 2: slow taiko, the swell, strings take the augmented second
  layer(2, stack(
    s("taiko:0 ~ ~ ~ ~ ~ taiko:1 ~").gain(.8).room(.5),
    s("swell:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.35).lpf(5000),
    n("<0 ~ 1 ~ 2 ~ 1 ~>".add("<0 0 0 0 2 2 -1 -1>")).scale("e3:spanish")
      .s("sawtooth").attack(.2).release(1).gain(.3).lpf(1200).room(.6).roomsize(6).orbit(2)))
).postgain(.33)
`,RF=`// hall-of-champions - D aeolian with a harmonic-minor V (C# in the A chord), 128 bpm.
// mood: epic, action. The PvP hall: heroic, ceremonial, then all-out. Timpani
// ostinato and full strings from level 0, a brass melody at level 2, the choir
// and war drums at level 3. C# is the raised 7th, the only note outside the key.
// Thirteen sections of eight cycles (3m15s before it repeats): four chord
// journeys, and the brass sings a new verse over each.
setcpm(128 / 4)

let A = "<Dm Bb^7 C Dm Gm7 Bb^7 A Dm>"
let B = "<Gm7 Dm Bb^7 C Dm F A Dm>"
