  // 3: the choir, doubled war drums
  layer(3, stack(
    chord(P).voicing().mode("below:d5").s("triangle").attack(.2).clip(.9).release(.15).gain(.3)
      .room(.8).roomsize(6).orbit(2),
    s("taiko:0 ~ taiko:1 taiko:0 ~ taiko:1 ~ taiko:0").gain(.5).room(.4)))
